## 📦 3. Complete Implementation Code

### Component A: Server-Side Token & Proxy Middleware
**Path:** `server/providers/voice/gemini.js`

```javascript
/**
 * @file Gemini Live WebSocket Token & Session Proxy
 * Brokers Google Generative AI credentials safely without exposing GEMINI_API_KEY.
 * @module server/providers/voice/gemini
 */

import { URL } from 'node:url';

const GEMINI_HOST = 'generativelanguage.googleapis.com';
const GEMINI_BIDI_PATH = '/ws/google.ai.generativelanguage.v1alpha.GenerativeService.BidiGenerateContent';

/**
 * Installs the Gemini token and connection preflight endpoint.
 * @param {import('vite').Connect.Server} middlewares
 */
export function geminiLiveProxy(middlewares) {
  middlewares.use('/api/gemini/session', async (req, res) => {
    if (req.method !== 'POST') {
      res.writeHead(405, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ ok: false, error: 'Method Not Allowed' }));
      return;
    }

    const apiKey = process.env.GEMINI_API_KEY || process.env.GOOGLE_AI_API_KEY;
    if (!apiKey) {
      res.writeHead(503, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({
        ok: false,
        error: 'GEMINI_API_KEY not configured. Add it in Provider Settings or .env',
      }));
      return;
    }

    // Return ephemeral connection parameters
    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({
      ok: true,
      provider: 'gemini',
      model: 'gemini-2.0-flash-exp',
      endpoint: `wss://${GEMINI_HOST}${GEMINI_BIDI_PATH}?key=${apiKey}`,
    }));
  });
}
```

