### Component B: Client-Side Gemini Live Streaming Provider
**Path:** `src/voice/providers/geminiLiveProvider.js`

```javascript
/**
 * @file Gemini 2.0 Multimodal Live Client Provider
 * Handles bidirectional PCM16 audio, viewport frame ingestion, and GEV tool calling.
 * @module voice/providers/geminiLiveProvider
 */

export class GeminiLiveProvider {
  /**
   * @param {Object} options
   * @param {Function} options.onToolCall - Dispatches GEV function calls (gevActions.js).
   * @param {Function} options.onAudioOutput - Streams raw PCM audio to Web Audio Context.
   * @param {Function} options.onStatusChange - Reports CONNECTING/LISTENING/ERROR status to HUD.
   */
  constructor({ onToolCall, onAudioOutput, onStatusChange }) {
    this._ws = null;
    this._onToolCall = onToolCall;
    this._onAudioOutput = onAudioOutput;
    this._onStatusChange = onStatusChange;
    this._active = false;
  }

  /**
   * Establishes bidirectional session with Gemini Live API.
   * @param {Array<Object>} toolDeclarations - Tool schemas mapped from GEV_REALTIME_TOOLS.
   */
  async connect(toolDeclarations = []) {
    this._onStatusChange('CONNECTING');

    const authRes = await fetch('/api/gemini/session', { method: 'POST' });
    if (!authRes.ok) {
      const err = await authRes.json().catch(() => ({}));
      this._onStatusChange('ERROR');
      throw new Error(err.error || 'Failed to authenticate Gemini Live session');
    }

    const { endpoint } = await authRes.json();
    this._ws = new WebSocket(endpoint);

    this._ws.onopen = () => {
      this._active = true;
      this._sendInitialSetup(toolDeclarations);
      this._onStatusChange('LISTENING');
    };

    this._ws.onmessage = (event) => this._handleMessage(event.data);
    this._ws.onerror = () => this._onStatusChange('ERROR');
    this._ws.onclose = () => {
      this._active = false;
      this._onStatusChange('OFF');
    };
  }

  /** Send session configuration, system instructions, and tool schemas. */
  _sendInitialSetup(tools) {
    const setupMessage = {
      setup: {
        model: 'models/gemini-2.0-flash-exp',
        generationConfig: {
          responseModalities: ['AUDIO'],
          speechConfig: {
            voiceConfig: {
              prebuiltVoiceConfig: { voiceName: 'Aoede' },
            },
          },
        },
        systemInstruction: {
          parts: [{
            text: `You are the onboard intelligence agent of God's Eye View (GEV). 
You control camera framing, entity tracking, layer toggles, and tactical queries. 
Always verify actions before confirming and keep intelligence summaries terse.`,
          }],
        },
        tools: [{ functionDeclarations: tools }],
      },
    };
    this._ws.send(JSON.stringify(setupMessage));
  }

  /**
   * Streams raw 16kHz PCM microphone audio to Gemini.
   * @param {Int16Array} pcmData
   */
  sendAudioChunk(pcmData) {
    if (!this._active || this._ws.readyState !== WebSocket.OPEN) return;
    const base64Audio = this._int16ToBase64(pcmData);
    this._ws.send(JSON.stringify({
      realtimeInput: {
        mediaChunks: [{
          mimeType: 'audio/pcm;rate=16000',
          data: base64Audio,
        }],
      },
    }));
  }

  /**
   * Streams downsampled viewport screenshot to ground spatial responses.
   * @param {string} jpegBase64
   */
  sendViewportScreenshot(jpegBase64) {
    if (!this._active || this._ws.readyState !== WebSocket.OPEN) return;
    this._ws.send(JSON.stringify({
      realtimeInput: {
        mediaChunks: [{
          mimeType: 'image/jpeg',
          data: jpegBase64,
        }],
      },
    }));
  }

  /** Ingests model responses, audio playback, and executes tactical tool calls. */
  async _handleMessage(rawPayload) {
    const msg = JSON.parse(rawPayload);

    // Audio stream output from model
    const audioData = msg?.serverContent?.modelTurn?.parts?.find((p) => p.inlineData?.mimeType?.startsWith('audio/'));
    if (audioData) {
      this._onAudioOutput(audioData.inlineData.data);
    }

    // Function/Tool Call received
    const call = msg?.toolCall?.functionCalls?.[0];
    if (call) {
      this._onStatusChange('EXECUTING');
      const result = await this._onToolCall(call.name, call.args);

      // Return tool response back to Gemini
      this._ws.send(JSON.stringify({
        toolResponse: {
          functionResponses: [{
            response: { output: result },
            id: call.id,
          }],
        },
      }));
      this._onStatusChange('LISTENING');
    }
  }

  _int16ToBase64(int16Array) {
    const bytes = new Uint8Array(int16Array.buffer);
    let binary = '';
    for (let i = 0; i < bytes.byteLength; i++) {
      binary += String.fromCharCode(bytes[i]);
    }
    return btoa(binary);
  }

  disconnect() {
    this._active = false;
    if (this._ws) this._ws.close();
  }
}
```

