/**
 * Maps GEV OpenAI function declarations to Google Gemini functionDeclaration schema.
 * @param {Array<Object>} openAiTools
 * @returns {Array<Object>} Gemini-compliant function declarations
 */
export function adaptToolsToGemini(openAiTools = []) {
  return openAiTools.map((tool) => {
    const declaration = tool.function || tool;
    return {
      name: declaration.name,
      description: declaration.description || '',
      parameters: declaration.parameters || { type: 'OBJECT', properties: {} },
    };
  });
}
