  try { gev.viewer.camera.cancelFlight(); } catch {}
  gev.viewer.camera.setView({
    destination: gev.viewer.scene.globe.ellipsoid.cartographicToCartesian({
      longitude: lon * rad, latitude: lat * rad, height,
    }),
    orientation: { heading: heading * rad, pitch: pitch * rad, roll: 0 },
  });
  gev.viewer.camera.changed.raiseEvent();
  gev.viewer.camera.moveEnd.raiseEvent();
}

// park above ACTIVATION_ALTITUDE, wait ~2 s, then arrive
