  return new Promise((resolve) => {
    const res = {
      statusCode: 200, headersSent: false, _h: {},
      setHeader(k, v) { this._h[k.toLowerCase()] = v; },
      writeHead(code, h = {}) { this.statusCode = code; this.headersSent = true; Object.assign(this._h, h); },
      end(body) { this.headersSent = true; resolve({ status: this.statusCode, body: body ? String(body) : '' }); },
    };
    handler({ url, method: 'GET', headers, socket: {} }, res, () => resolve({ status: 'next' }));
  });
}

